@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2C2C2C;
  font-family: "Montserrat", sans-serif;
}

/* ===== Ad Root ===== */
#ad-320x480 {
  width: 320px;
  height: 480px;
  background: #F4ECDC;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* ===== Header ===== */
.ad-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px 8px;
  background: #FFFFFF;
  flex-shrink: 0;
  z-index: 10;
}

.ad-logo {
  height: 28px;
  width: auto;
  display: block;
}

.eyebrow {
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #FFFFFF;
  background: #1F3A5F;
  padding: 3px 7px;
  border-radius: 2px;
}

/* ===== Hero Text ===== */
.ad-hero-text {
  padding: 10px 14px 8px;
  background: #1F3A5F;
  flex-shrink: 0;
  position: relative;
  z-index: 5;
}

.subhead {
  font-family: "Montserrat", sans-serif;
  font-weight: 600;
  font-size: 9px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #C8A24B;
  margin-bottom: 2px;
}

.headline {
  font-family: "Playfair Display", serif;
  font-weight: 700;
  font-size: 28px;
  line-height: 1.1;
  color: #FFFFFF;
  display: inline-block;
}

.headline em {
  font-style: italic;
  color: #C8A24B;
  font-weight: 400;
}

.discount-badge {
  display: inline-block;
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 10px;
  color: #F4ECDC;
  margin-top: 3px;
}

.discount-badge strong {
  font-size: 14px;
  font-weight: 700;
  color: #E84B6A;
  margin-left: 3px;
}

/* ===== Slideshow ===== */
.slideshow {
  position: relative;
  flex: 1;
  overflow: hidden;
  background: #000000;
}

.slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.7s ease-in-out;
  display: flex;
  align-items: center;
  justify-content: center;
}

.slide.active {
  opacity: 1;
}

.slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

/* Gradient overlay on slide for legibility */
.slideshow::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: linear-gradient(to top, rgba(31, 58, 95, 0.55), transparent);
  pointer-events: none;
  z-index: 2;
}

/* ===== Slide Dots ===== */
.slide-dots {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 5px;
  z-index: 4;
}

/* Hide dots when carousel has only one effective slide */
#ad-320x480 .slide-dots.hidden {
  display: none;
}

.dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(244, 236, 220, 0.5);
  cursor: pointer;
  transition: background 0.3s, transform 0.3s;
  border: none;
  padding: 0;
}

.dot.active {
  background: #C8A24B;
  transform: scale(1.3);
}

/* ===== Footer ===== */
.ad-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px 20px;
  background: #FFFFFF;
  border-top: 2px solid #C8A24B;
  flex-shrink: 0;
  z-index: 10;
}

.body-copy {
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 8px;
  color: #2C2C2C;
  line-height: 1.3;
  flex: 1;
  padding-right: 8px;
}

/* ===== CTA Button ===== */
.cta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #E84B6A;
  color: #FFFFFF;
  text-decoration: none;
  border-radius: 2px;
  padding: 8px 14px;
  flex-shrink: 0;
  transition: background 0.25s ease, transform 0.15s ease;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18);
}

.cta-btn:hover,
.cta-btn:focus {
  background: #C8A24B;
  transform: scale(1.04);
  outline: none;
}

.cta-btn:active {
  transform: scale(0.97);
}

.cta-label {
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 11px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #FFFFFF;
  white-space: nowrap;
}

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  .slide {
    transition: none;
  }
  .dot {
    transition: none;
  }
  .cta-btn {
    transition: none;
  }
}

